using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class InstallGeneratedVehicles {
 const string Characters="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/CH07/",Vehicles="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedVehicles20261003/";
 static Transform Group(Transform parent,string name,Vector3 position){var g=new GameObject(name);g.transform.SetParent(parent,false);g.transform.localPosition=position;return g.transform;}
 static Transform Bone(Animator animator,string name)=>animator.GetComponentsInChildren<Transform>(true).Single(t=>t.name==name);
 static RuntimeAnimatorController Controller(string pose){string path=Characters+"role-"+pose+".controller";var existing=AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(path);if(existing!=null)return existing;var controller=AnimatorController.CreateAnimatorControllerAtPath(path);var sm=controller.layers[0].stateMachine;var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(Characters+pose+".anim");foreach(var name in new[]{"idle","walk","run","attack_once","attack_loop","die"}){var state=sm.AddState(name);state.motion=clip;if(name=="idle")sm.defaultState=state;}return controller;}
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Idle required");EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/Jamsil.unity");var d=Object.FindFirstObjectByType<Chapter45Director>();if(d.transform.Find("Preserved_PreGeneratedVehicles_20261003")!=null)throw new Exception("Already installed");string backup="outputs/chapter45-detailed-design-2026-10-03/scene-recovery/Jamsil-before-generated-vehicles.unity";File.Copy(d.gameObject.scene.path,backup,false);var archive=Group(d.transform,"Preserved_PreGeneratedVehicles_20261003",Vector3.zero);archive.gameObject.SetActive(false);var report=new List<object>();foreach(var hazard in d.hazards.Where(h=>h.name.Contains("kickboard")||h.name.Contains("motorcycle"))){bool bike=hazard.name.Contains("motorcycle");var body=hazard.body;var before=body.GetComponents<Collider>().Select(c=>EditorJsonUtility.ToJson(c)).ToArray();var hazardBefore=EditorJsonUtility.ToJson(hazard);foreach(var old in body.Cast<Transform>().ToArray()){old.SetParent(archive,true);old.gameObject.SetActive(false);}var hull=body.GetComponent<Renderer>();if(hull!=null)hull.enabled=false;var assembly=Group(body,"Generated vehicle and own rig rider",new Vector3(0,-1,0));var vehicle=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Vehicles+(bike?"DetailedDeliveryBike":"DetailedKickboard")+".prefab"),assembly);float height=bike?1.25f:1.15f;var points=new List<Vector3>();foreach(var filter in vehicle.GetComponentsInChildren<MeshFilter>())foreach(var v in filter.sharedMesh.vertices)points.Add(vehicle.transform.InverseTransformPoint(filter.transform.TransformPoint(v)));var top=points.Where(v=>v.y>.86f).ToArray();float front=bike?top.Average(v=>v.z):top.Average(v=>v.x);float yaw=bike?(front>=0?0:180):(front>=0?-90:90);vehicle.transform.localRotation=Quaternion.Euler(0,yaw,0);vehicle.transform.localScale=Vector3.one*height;var rider=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Characters+"CH07.prefab"),assembly);rider.name="Own rig "+(bike?"seated delivery rider":"kickboard rider");rider.transform.localPosition=new Vector3(0,bike?.25f:.16f,bike?-.18f:-.10f);var animator=rider.GetComponentInChildren<Animator>();animator.runtimeAnimatorController=Controller(bike?"bikeride":"kickride");var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(Characters+(bike?"bikeride":"kickride")+".anim");clip.SampleAnimation(animator.gameObject,0);var pose=assembly.gameObject.AddComponent<Chapter45RiderPose>();pose.director=d;pose.animator=animator;pose.rider=rider.transform;pose.hips=Bone(animator,"Hips");pose.leftGrip=Group(assembly,"Left handle grip",new Vector3(-.22f,bike?.94f:1.10f,bike?.44f:.36f));pose.rightGrip=Group(assembly,"Right handle grip",new Vector3(.22f,bike?.94f:1.10f,bike?.44f:.36f));pose.leftArm=Bone(animator,"LeftArm");pose.leftForearm=Bone(animator,"LeftForeArm");pose.leftHand=Bone(animator,"LeftHand");pose.rightArm=Bone(animator,"RightArm");pose.rightForearm=Bone(animator,"RightForeArm");pose.rightHand=Bone(animator,"RightHand");pose.leftThigh=Bone(animator,"LeftUpLeg");pose.leftShin=Bone(animator,"LeftLeg");pose.leftFoot=Bone(animator,"LeftFoot");pose.rightThigh=Bone(animator,"RightUpLeg");pose.rightShin=Bone(animator,"RightLeg");pose.rightFoot=Bone(animator,"RightFoot");if(bike){pose.seat=Group(assembly,"Seated pelvis anchor",new Vector3(0,.80f,-.20f));pose.leftFootTarget=Group(assembly,"Left footrest",new Vector3(-.19f,.28f,.05f));pose.rightFootTarget=Group(assembly,"Right footrest",new Vector3(.19f,.28f,.05f));}pose.ApplyPose();if(!before.SequenceEqual(body.GetComponents<Collider>().Select(c=>EditorJsonUtility.ToJson(c)))||hazardBefore!=EditorJsonUtility.ToJson(hazard))throw new Exception("Hazard contract changed");if(assembly.GetComponentsInChildren<Collider>(true).Length!=0)throw new Exception("Visual collider added");report.Add(new{hazard=hazard.name,height,yaw,topFront=front,ownMotion=clip.name,collidersPreserved=true,warningAndDamagePreserved=true});}EditorSceneManager.MarkSceneDirty(d.gameObject.scene);EditorSceneManager.SaveScene(d.gameObject.scene);AssetDatabase.SaveAssets();return new{items=report,generatedEnvironment="Local TRELLIS.2",generatedRider="Meshy own rig and own retargeted action",sceneApplied=true};}
}
